# 📣️ WP4 hand-off tables: the machine assignment of every ShellState member and narrow-parameter free fn after re-homing.
import sys, os, json, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from t1lib import *
plan1 = PLAN1
rank = assign_rank = None
import assign
RANK = assign.RANK
rows = []
out = ['# 📣️ RENDERER-WP4 hand-off: method and free-function assignment', '',
 'Generated by `rwp4-tools/gen_handoff.py` from `🗑️generated/rwp4-t1-plan.json` (call graph and field touches of the post-S0 tree; mutability from `plan_t1.field_mutations`). `crate` is the final home, `appendix B` the first-cut home of the plan; they differ when step 5 of 7.4 lifted a caller above an upward call or lowered a helper to its lowest caller.', '',
 'Tier-1 methods live in `impl <Struct>`; their extra parameters are components in rank order, `&mut` where `mut` is set. Use-case rows stay `impl ShellState` in the staging file of their crate until WP5 turns them into bundle methods; their callers/bodies already address the components (`self.<component>.<field>`).', '']
byc = collections.OrderedDict((c, []) for c in RANK)
for n, v in sorted(plan1.items()):
    byc[v['crate']].append((n, v))
for c, lst in byc.items():
    if not lst: continue
    out.append(f'## {c} ({len(lst)})'); out.append('')
    out.append('| name | kind | struct | receiver | extra components | appendix B |'); out.append('|---|---|---|---|---|---|')
    for n, v in lst:
        if v['tier1']:
            ps = ', '.join(('&mut ' if m else '&') + s for s, m in v['params']) or '-'
            kind = 'free fn' if v.get('recv') == 'free' else ('free fn (was assoc)' if v.get('recv') is None else 'method')
            out.append(f"| `{n}` | {kind} | {v['struct'] or '-'} | {v['recv'] or '-'} | {ps} | {v['from_appendix_b'] if v['from_appendix_b'] != c else '='} |")
        else:
            out.append(f"| `{n}` | use case | ShellState | - | - | {v['from_appendix_b'] if v['from_appendix_b'] != c else '='} |")
    out.append('')
open(sys.argv[1], 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print(len(plan1), 'rows')
